insert into public.diagnostic_questions(id,question_text,category,subcategory,difficulty,option_a,option_b,option_c,option_d,correct_answer,explanation,estimated_time_seconds,active) select id,question_text,category,subcategory,difficulty,option_a,option_b,option_c,option_d,correct_answer,explanation,estimated_time_seconds,true from jsonb_to_recordset($diagnostic$[{"id":"ev-grammar-16","category":"english_verbal","subcategory":"Grammar","question_text":"Choose the grammatically correct sentence.","options":["Less candidates attended than expected.","Despite of the delay, fewer candidates attended than expected.","Fewer candidates attended than expected.","The team discussed about why fewer candidates attended than expected."],"correct_answer":"C","explanation":"The first sentence follows standard agreement, tense and usage rules.","estimated_time_seconds":60,"difficulty":1,"option_a":"Less candidates attended than expected.","option_b":"Despite of the delay, fewer candidates attended than expected.","option_c":"Fewer candidates attended than expected.","option_d":"The team discussed about why fewer candidates attended than expected."},{"id":"ev-grammar-17","category":"english_verbal","subcategory":"Grammar","question_text":"Choose the grammatically correct sentence.","options":["There are less uncertainty now.","Despite of the delay, there is less uncertainty now.","The team discussed about why there is less uncertainty now.","There is less uncertainty now."],"correct_answer":"D","explanation":"The first sentence follows standard agreement, tense and usage rules.","estimated_time_seconds":60,"difficulty":1,"option_a":"There are less uncertainty now.","option_b":"Despite of the delay, there is less uncertainty now.","option_c":"The team discussed about why there is less uncertainty now.","option_d":"There is less uncertainty now."},{"id":"ev-grammar-18","category":"english_verbal","subcategory":"Grammar","question_text":"Choose the grammatically correct sentence.","options":["The principal reason is the delayed approval.","The principal reason are the delayed approval.","Despite of the delay, the principal reason is the delayed approval.","The team discussed about why the principal reason is the delayed approval."],"correct_answer":"A","explanation":"The first sentence follows standard agreement, tense and usage rules.","estimated_time_seconds":60,"difficulty":2,"option_a":"The principal reason is the delayed approval.","option_b":"The principal reason are the delayed approval.","option_c":"Despite of the delay, the principal reason is the delayed approval.","option_d":"The team discussed about why the principal reason is the delayed approval."},{"id":"ev-grammar-19","category":"english_verbal","subcategory":"Grammar","question_text":"Choose the grammatically correct sentence.","options":["Having reviewed the evidence, the decision was changed.","Having reviewed the evidence, the panel changed its decision.","Despite of the delay, having reviewed the evidence, the panel changed its decision.","The team discussed about why having reviewed the evidence, the panel changed its decision."],"correct_answer":"B","explanation":"The first sentence follows standard agreement, tense and usage rules.","estimated_time_seconds":60,"difficulty":2,"option_a":"Having reviewed the evidence, the decision was changed.","option_b":"Having reviewed the evidence, the panel changed its decision.","option_c":"Despite of the delay, having reviewed the evidence, the panel changed its decision.","option_d":"The team discussed about why having reviewed the evidence, the panel changed its decision."},{"id":"ev-grammar-20","category":"english_verbal","subcategory":"Grammar","question_text":"Choose the grammatically correct sentence.","options":["The results is consistent with the hypothesis.","Despite of the delay, the results are consistent with the hypothesis.","The results are consistent with the hypothesis.","The team discussed about why the results are consistent with the hypothesis."],"correct_answer":"C","explanation":"The first sentence follows standard agreement, tense and usage rules.","estimated_time_seconds":60,"difficulty":2,"option_a":"The results is consistent with the hypothesis.","option_b":"Despite of the delay, the results are consistent with the hypothesis.","option_c":"The results are consistent with the hypothesis.","option_d":"The team discussed about why the results are consistent with the hypothesis."},{"id":"ev-grammar-21","category":"english_verbal","subcategory":"Grammar","question_text":"Choose the grammatically correct sentence.","options":["It are essential that every applicant be present.","Despite of the delay, it is essential that every applicant be present.","The team discussed about why it is essential that every applicant be present.","It is essential that every applicant be present."],"correct_answer":"D","explanation":"The first sentence follows standard agreement, tense and usage rules.","estimated_time_seconds":60,"difficulty":2,"option_a":"It are essential that every applicant be present.","option_b":"Despite of the delay, it is essential that every applicant be present.","option_c":"The team discussed about why it is essential that every applicant be present.","option_d":"It is essential that every applicant be present."},{"id":"ev-grammar-22","category":"english_verbal","subcategory":"Grammar","question_text":"Choose the grammatically correct sentence.","options":["Neither the server nor the clients are responding.","Neither the server nor the clients is responding.","Despite of the delay, neither the server nor the clients are responding.","The team discussed about why neither the server nor the clients are responding."],"correct_answer":"A","explanation":"The first sentence follows standard agreement, tense and usage rules.","estimated_time_seconds":60,"difficulty":2,"option_a":"Neither the server nor the clients are responding.","option_b":"Neither the server nor the clients is responding.","option_c":"Despite of the delay, neither the server nor the clients are responding.","option_d":"The team discussed about why neither the server nor the clients are responding."},{"id":"ev-grammar-23","category":"english_verbal","subcategory":"Grammar","question_text":"Choose the grammatically correct sentence.","options":["The quality of the samples were satisfactory.","The quality of the samples was satisfactory.","Despite of the delay, the quality of the samples was satisfactory.","The team discussed about why the quality of the samples was satisfactory."],"correct_answer":"B","explanation":"The first sentence follows standard agreement, tense and usage rules.","estimated_time_seconds":60,"difficulty":3,"option_a":"The quality of the samples were satisfactory.","option_b":"The quality of the samples was satisfactory.","option_c":"Despite of the delay, the quality of the samples was satisfactory.","option_d":"The team discussed about why the quality of the samples was satisfactory."},{"id":"ev-grammar-24","category":"english_verbal","subcategory":"Grammar","question_text":"Choose the grammatically correct sentence.","options":["She explained the procedure clear and concise.","Despite of the delay, she explained the procedure clearly and concisely.","She explained the procedure clearly and concisely.","The team discussed about why she explained the procedure clearly and concisely."],"correct_answer":"C","explanation":"The first sentence follows standard agreement, tense and usage rules.","estimated_time_seconds":60,"difficulty":3,"option_a":"She explained the procedure clear and concise.","option_b":"Despite of the delay, she explained the procedure clearly and concisely.","option_c":"She explained the procedure clearly and concisely.","option_d":"The team discussed about why she explained the procedure clearly and concisely."},{"id":"ev-grammar-25","category":"english_verbal","subcategory":"Grammar","question_text":"Choose the grammatically correct sentence.","options":["By next June, they will completed the project.","Despite of the delay, by next june, they will have completed the project.","The team discussed about why by next june, they will have completed the project.","By next June, they will have completed the project."],"correct_answer":"D","explanation":"The first sentence follows standard agreement, tense and usage rules.","estimated_time_seconds":60,"difficulty":3,"option_a":"By next June, they will completed the project.","option_b":"Despite of the delay, by next june, they will have completed the project.","option_c":"The team discussed about why by next june, they will have completed the project.","option_d":"By next June, they will have completed the project."},{"id":"db-1-1","category":"database_technical","subcategory":"SQL Filtering","question_text":"Which clause filters rows before grouping?","options":["WHERE","HAVING","ORDER BY","DISTINCT"],"correct_answer":"A","explanation":"WHERE filters input rows; HAVING filters groups.","estimated_time_seconds":60,"difficulty":1,"option_a":"WHERE","option_b":"HAVING","option_c":"ORDER BY","option_d":"DISTINCT"},{"id":"db-1-2","category":"database_technical","subcategory":"Aggregation","question_text":"Which clause filters aggregate groups?","options":["WHERE","HAVING","SELECT DISTINCT","LIMIT"],"correct_answer":"B","explanation":"HAVING is evaluated on groups after GROUP BY.","estimated_time_seconds":60,"difficulty":1,"option_a":"WHERE","option_b":"HAVING","option_c":"SELECT DISTINCT","option_d":"LIMIT"},{"id":"db-1-3","category":"database_technical","subcategory":"Keys","question_text":"What property must every primary-key value have?","options":["It may repeat","It must be text","It is unique and non-null","It must reference another table"],"correct_answer":"C","explanation":"A primary key uniquely identifies a row and cannot be null.","estimated_time_seconds":60,"difficulty":2,"option_a":"It may repeat","option_b":"It must be text","option_c":"It is unique and non-null","option_d":"It must reference another table"},{"id":"db-1-4","category":"database_technical","subcategory":"Foreign Keys","question_text":"What does a foreign key primarily enforce?","options":["Sort order","Column encryption","Query caching","Referential integrity"],"correct_answer":"D","explanation":"It constrains values to referenced candidate-key values.","estimated_time_seconds":60,"difficulty":2,"option_a":"Sort order","option_b":"Column encryption","option_c":"Query caching","option_d":"Referential integrity"},{"id":"db-1-5","category":"database_technical","subcategory":"Normalization","question_text":"Which normal form removes partial dependency on a composite key?","options":["Second normal form","First normal form","Third normal form","BCNF only"],"correct_answer":"A","explanation":"2NF removes partial dependencies on a candidate key.","estimated_time_seconds":60,"difficulty":2,"option_a":"Second normal form","option_b":"First normal form","option_c":"Third normal form","option_d":"BCNF only"},{"id":"db-1-6","category":"database_technical","subcategory":"Transactions","question_text":"Which ACID property ensures committed data survives failure?","options":["Atomicity","Durability","Isolation","Consistency"],"correct_answer":"B","explanation":"Durability preserves committed changes.","estimated_time_seconds":60,"difficulty":2,"option_a":"Atomicity","option_b":"Durability","option_c":"Isolation","option_d":"Consistency"},{"id":"db-1-7","category":"database_technical","subcategory":"Transactions","question_text":"Which ACID property makes a transaction all-or-nothing?","options":["Isolation","Durability","Atomicity","Availability"],"correct_answer":"C","explanation":"Atomicity prevents partial transactions.","estimated_time_seconds":60,"difficulty":2,"option_a":"Isolation","option_b":"Durability","option_c":"Atomicity","option_d":"Availability"},{"id":"db-1-8","category":"database_technical","subcategory":"Indexes","question_text":"What is the usual trade-off of adding an index?","options":["Faster writes with no cost","Automatic normalization","Guaranteed uniqueness for every index","Faster reads but extra storage and write cost"],"correct_answer":"D","explanation":"Indexes accelerate matching reads but must be maintained on writes.","estimated_time_seconds":60,"difficulty":3,"option_a":"Faster writes with no cost","option_b":"Automatic normalization","option_c":"Guaranteed uniqueness for every index","option_d":"Faster reads but extra storage and write cost"},{"id":"db-1-9","category":"database_technical","subcategory":"JOIN","question_text":"Which join retains every row from the left table?","options":["LEFT JOIN","INNER JOIN","CROSS JOIN","SELF JOIN"],"correct_answer":"A","explanation":"LEFT JOIN preserves all left rows.","estimated_time_seconds":60,"difficulty":3,"option_a":"LEFT JOIN","option_b":"INNER JOIN","option_c":"CROSS JOIN","option_d":"SELF JOIN"},{"id":"db-1-10","category":"database_technical","subcategory":"NULL","question_text":"Which predicate correctly tests missing SQL values?","options":["= NULL","IS NULL","== NULL","NULL()"],"correct_answer":"B","explanation":"NULL uses IS NULL because equality with NULL is unknown.","estimated_time_seconds":60,"difficulty":3,"option_a":"= NULL","option_b":"IS NULL","option_c":"== NULL","option_d":"NULL()"},{"id":"db-1-11","category":"database_technical","subcategory":"Grouping","question_text":"A query selects department and COUNT(*). What else is normally required?","options":["ORDER BY department","HAVING department","GROUP BY department","DISTINCT COUNT"],"correct_answer":"C","explanation":"Non-aggregated selected columns normally belong in GROUP BY.","estimated_time_seconds":60,"difficulty":1,"option_a":"ORDER BY department","option_b":"HAVING department","option_c":"GROUP BY department","option_d":"DISTINCT COUNT"},{"id":"db-1-12","category":"database_technical","subcategory":"Isolation","question_text":"What anomaly is prevented when a transaction cannot read uncommitted changes?","options":["Lost index","Dead column","Schema drift","Dirty read"],"correct_answer":"D","explanation":"Dirty reads observe another transaction's uncommitted work.","estimated_time_seconds":60,"difficulty":1,"option_a":"Lost index","option_b":"Dead column","option_c":"Schema drift","option_d":"Dirty read"},{"id":"db-1-13","category":"database_technical","subcategory":"Query Logic","question_text":"COUNT(column_name) differs from COUNT(*) because it does what?","options":["Ignores NULL values in that column","Counts distinct values only","Counts tables","Returns text"],"correct_answer":"A","explanation":"COUNT(column) ignores NULL; COUNT(*) counts rows.","estimated_time_seconds":60,"difficulty":2,"option_a":"Ignores NULL values in that column","option_b":"Counts distinct values only","option_c":"Counts tables","option_d":"Returns text"},{"id":"db-1-14","category":"database_technical","subcategory":"Set Operations","question_text":"What does UNION do by default?","options":["Keeps all duplicates","Removes duplicate rows","Joins columns by keys","Updates both queries"],"correct_answer":"B","explanation":"UNION applies duplicate elimination; UNION ALL does not.","estimated_time_seconds":60,"difficulty":2,"option_a":"Keeps all duplicates","option_b":"Removes duplicate rows","option_c":"Joins columns by keys","option_d":"Updates both queries"},{"id":"db-1-15","category":"database_technical","subcategory":"Subqueries","question_text":"A correlated subquery is evaluated with reference to what?","options":["Only system tables","A stored procedure","A row from the outer query","An index page"],"correct_answer":"C","explanation":"It references values supplied by the outer query.","estimated_time_seconds":60,"difficulty":2,"option_a":"Only system tables","option_b":"A stored procedure","option_c":"A row from the outer query","option_d":"An index page"}]$diagnostic$::jsonb) as x(id text,question_text text,category text,subcategory text,difficulty numeric,option_a text,option_b text,option_c text,option_d text,correct_answer char(1),explanation text,estimated_time_seconds integer) on conflict(id) do update set question_text=excluded.question_text,category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,option_a=excluded.option_a,option_b=excluded.option_b,option_c=excluded.option_c,option_d=excluded.option_d,correct_answer=excluded.correct_answer,explanation=excluded.explanation,estimated_time_seconds=excluded.estimated_time_seconds,active=true;
